package com.fream.back.domain.m52.service.command;

import com.fream.back.domain.m52.dto.Xbp24DTO;
import com.fream.back.domain.m52.dto.Xbp24RequestDTO;
import com.fream.back.domain.m52.entity.Xbp24;
import com.fream.back.domain.m52.entity.Xrv73;
import com.fream.back.domain.m52.entity.Xbp24Type;
import com.fream.back.domain.m52.exception.Xbp24ErrorCode;
import com.fream.back.domain.m52.exception.Xbp24Exception;
import com.fream.back.domain.m52.repository.Xbp24Repository;
import com.fream.back.domain.m99.entity.Xhq12;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.domain.m22.repository.Xjm45Repository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

@Service
@Transactional
@RequiredArgsConstructor
@Slf4j
public class Xbp24CommandService {

    private final Xbp24Repository notificationRepository;
    private final Xjm45Repository userRepository;
    private final SimpMessagingTemplate messagingTemplate;
    private final RedisTemplate<String, String> redisTemplate;

    private static final String REDIS_KEY_PREFIX = "WebSocket:Xjm45:";
    private static final String WEBSOCKET_DESTINATION = "/queue/notifications";
    private static final int REDIS_TTL_MINUTES = 30;




    public Xbp24DTO createNotification(Long userId, Xrv73 category, Xbp24Type type, String message) {
        try {
            Xjm45 user = userRepository.findById(userId)
                    .orElseThrow(() -> new Xbp24Exception(
                            Xbp24ErrorCode.NOTIFICATION_USER_NOT_FOUND,
                            "사용자 ID: " + userId + "를 찾을 수 없습니다."
                    ));

            Xbp24 notification = buildNotification(user, category, type, message);
            Xbp24 savedNotification = notificationRepository.save(notification);
            log.info("알림 생성 완료: 사용자={}, 카테고리={}, 타입={}", user.getEmail(), category, type);


            sendRealTimeNotification(user.getEmail(), toDTO(savedNotification));

            return toDTO(savedNotification);
        } catch (Xbp24Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("알림 생성 중 오류 발생: 사용자ID={}, 카테고리={}, 타입={}, 오류={}",
                    userId, category, type, e.getMessage(), e);
            throw new Xbp24Exception(Xbp24ErrorCode.NOTIFICATION_CREATION_FAILED, e);
        }
    }




    public List<Xbp24DTO> createNotificationForAll(Xbp24RequestDTO requestDTO) {
        try {
            List<Xjm45> allUsers = userRepository.findAll();
            if (allUsers.isEmpty()) {
                log.warn("알림 대상 사용자가 없습니다.");
                return List.of();
            }

            log.info("전체 사용자 알림 생성 시작: 카테고리={}, 타입={}, 대상 사용자 수={}",
                    requestDTO.getCategory(), requestDTO.getType(), allUsers.size());

            List<Xbp24> notifications = createNotificationsForUsers(
                    allUsers, requestDTO.getCategory(), requestDTO.getType(), requestDTO.getMessage());

            List<Xbp24> savedNotifications = notificationRepository.saveAll(notifications);
            log.info("전체 사용자 알림 생성 완료: 카테고리={}, 타입={}, 생성된 알림 수={}",
                    requestDTO.getCategory(), requestDTO.getType(), savedNotifications.size());


            broadcastNotificationsToConnectedUsers(allUsers, savedNotifications);

            return toDTOList(savedNotifications);
        } catch (Exception e) {
            log.error("전체 사용자 알림 생성 중 오류 발생: 카테고리={}, 타입={}, 오류={}",
                    requestDTO.getCategory(), requestDTO.getType(), e.getMessage(), e);
            throw new Xbp24Exception(Xbp24ErrorCode.NOTIFICATION_CREATION_FAILED, e);
        }
    }




    public void markAsRead(Long notificationId, String email) {
        try {
            Xbp24 notification = notificationRepository.findById(notificationId)
                    .orElseThrow(() -> new Xbp24Exception(
                            Xbp24ErrorCode.NOTIFICATION_NOT_FOUND,
                            "알림 ID: " + notificationId + "를 찾을 수 없습니다."
                    ));


            if (!notification.getUser().getEmail().equals(email)) {
